const host = this.getFormRef();
const listField = this;
const ci = dataRow.consult_info || null;
const curUnit = (dataRow.unit_to && dataRow.unit_to.value) || '';
const ctx = {
  tran_id: String(dataRow._id),
  cur_unit: curUnit,
  visit_priority: dataRow.visit_priority || '10',
  tran_note: '',
  consult_id: ''
};
if (ci && ci.clinic && String(ci.clinic) !== String(curUnit)) {
  // ต้นทาง → ส่งไปคลินิก consult + stamp accept
  ctx.unit_to = { value: ci.clinic, label: ci.to_label || ci.clinic };
  ctx.tran_note = ci.reason || '';
  ctx.visit_priority = ci.priority || ctx.visit_priority;
  ctx.consult_id = ci.consult_id || '';
} else if (ci && ci.reply && String(ci.clinic) === String(curUnit) && dataRow.unit_from && dataRow.unit_from.value) {
  // ปลายทาง + ขอส่งกลับ → prefill คลินิกต้นทาง (tran.unit_from — ไม่ใช่ consult_info)
  ctx.unit_to = { value: dataRow.unit_from.value, label: dataRow.unit_from.label || dataRow.unit_from.value };
}
host.openForm('6a4f828d22f95f21b606d9a2', '', '', ctx, {
  params: ctx,
  cancelCallback: () => {
    host.subFormClose();
    const ed = listField.getFieldEditor(); if (ed) ed.handleRefresh();
    const other = listField.getFieldRef(listField.field.options.name === 'visit_unit' ? 'visit_room' : 'visit_unit');
    if (other && other.getFieldEditor()) other.getFieldEditor().handleRefresh();
  }
});

