options.onCreated:
const s = this.vueState
const field = this
s.tran = null   // visit tran ที่เลือกจากคิว — เซ็ตโดยปุ่ม EMR / onMounted

s.pt = () => (s.tran && s.tran.vid && s.tran.vid.pid) || {}
s.ptName = () => {
  const p = s.pt()
  return ((p.prename && p.prename.label) || '') + (p.p_fname || '') + ' ' + (p.p_lname || '')
}
s.picUrl = () => {
  const p = s.pt()
  return (Array.isArray(p.p_pic) && p.p_pic[0] && p.p_pic[0].url) || ''
}
s.initial = () => { const p = s.pt(); return p.p_fname ? p.p_fname.charAt(0) : '?' }
s.genderLabel = () => ({ '1': 'ชาย', '2': 'หญิง' })[s.pt().p_gender] || '-'
s.aboLabel = () => {
  const m = { '1': 'A', '2': 'B', '3': 'AB', '4': 'O', '5': 'ไม่ทราบ', '9': 'ไม่ทราบ' }
  const p = s.pt()
  return m[p.p_abogroup] || p.p_abogroup || '-'
}
s.visitTime = () => {
  const t = s.tran && s.tran.checkin_at
  return t ? field.dayjs(t).format('DD/MM/YYYY HH:mm') : '-'
}

// เปิดฟอร์มผู้ป่วย (PERSON) — id ผู้ป่วยอยู่ที่ vid.xtbxlv1_xfx_id (= pid.value ของ visit)
s.openPatient = () => {
  const pidId = s.tran && s.tran.vid && s.tran.vid.xtbxlv1_xfx_id
  if (!pidId) { field.alert('ไม่พบ id ผู้ป่วยใน visit นี้', 'warning'); return }
  const form = field.getFormRef()
  form.openForm('6a37d3bd4cfbfdbe257fc912', String(pidId), '', null, {
    afterSaveCallback: (saved) => {
      form.subFormClose()
      if (!saved) return
      const p = s.tran.vid.pid
      if (p) {
        ['hn', 'prename', 'p_fname', 'p_lname', 'p_gender', 'age', 'p_abogroup', 'birth_date', 'p_pic']
          .forEach((k) => { if (k in saved) p[k] = saved[k] })
      }
      // sync allergy_tags ลง visit_tran จริง → ws เด้งจอคิว + เอา tags กลับมาอัปเดตการ์ด
      form.userState.runProcess('6a50cc20e97c6d6bbf111ce0', { person_id: String(s.tran.vid.xtbxlv1_xfx_id), sync_allergy: true }, (res) => {
        const d = res.data || {}
        if (d.success && 'allergy_tags' in d) s.tran.allergy_tags = d.allergy_tags || []
      }, (err) => field.alert('sync การแพ้ไม่สำเร็จ: ' + ((err && err.message) || err), 'error'))
    }

  })
}

s.bmiRec = null   // record BMI ล่าสุดของ visit นี้

s.loadBmi = () => {
  s.bmiRec = null
  const visitId = s.tran && s.tran.vid && s.tran.vid.value
  if (!visitId) return
  field.getFormRef().userState.crudGetAll({
    sdProvider: {
      providerId: '6a4689ef39179670f85ba2a2',   // ฟอร์ม BMI
      providerType: 'FORM',
      params: { vid: String(visitId) },
      options: {
        where: "`vid.value` = CONVERT(:vid, 'objectId')",
        orderBy: [{ column: 'created_at', sort: 'DESC' }],
        limit: 1,
        page: 1
      }

    },
    totalEnable: false
  }, (res) => { s.bmiRec = (res.data && res.data[0]) || null })
}

// เซ็ตคนไข้ + โหลด BMI — ให้ปุ่ม EMR / onMounted เรียกตัวนี้แทนเซ็ต tran ตรง
s.setTran = (row) => {
  s.tran = row; s.loadBmi(); s.loadVs(); s.tickExam()
  // ยังไม่เลือกผู้ป่วย → ซ่อนโซน SOAP ทั้งแถบ (container hide แค่ซ่อน ไม่ล้างค่า field)
  const box = field.getFieldRef('emr_box')
  if (box) { row ? box.show() : box.hide() }
  // เซ็ต visit id ลง field vid + refresh consult — หน่วง 1 tick กันเคส mount แรกที่ field ยังไม่ register
    // เซ็ต visit id ลง field vid + refresh consult + registry — หน่วง 1 tick กันเคส mount แรกที่ field ยังไม่ register
  setTimeout(() => {
    const vidVal = (row && row.vid && row.vid.value) ? String(row.vid.value) : ''
    const f = field.getFieldRef('vid')
    if (f) f.setValue(vidVal)
    const cs = field.getFieldRef('consult_box')
    if (cs && cs.vueState && cs.vueState.load) cs.vueState.load(vidVal || null)

      const cbn = field.getFieldRef('consult_banner')
      if (cbn) {
        if (cbn.vueState && cbn.vueState.load) cbn.vueState.load(row || null)
        // ซ่อน field ทั้งอันถ้าไม่มี consult ฝั่งรับ (clinic===unit_to) — กันช่องว่าง
        const ci = row && row.consult_info
        const showBanner = !!(ci && ci.clinic && row.unit_to && String(ci.clinic) === String(row.unit_to.value))
        showBanner ? cbn.show() : cbn.hide()
      }


    // refresh Disease Registry — person id อยู่ที่ vid.xtbxlv1_xfx_id (= pid.value ของ visit)
    const rg = field.getFieldRef('registry_card')
    if (rg && rg.vueState && rg.vueState.load) {
      const personId = (row && row.vid && row.vid.xtbxlv1_xfx_id) ? String(row.vid.xtbxlv1_xfx_id) : null
      rg.vueState.load(personId, (row && row.vid && row.vid.pid) || null, vidVal || null)
    }
  }, 0)

}



// เปิดฟอร์ม BMI — dataId null = เพิ่มใหม่ (parent = visit), มีค่า = แก้ record เดิม
s.openBmi = (dataId) => {
  const visitId = s.tran && s.tran.vid && s.tran.vid.value
  if (!visitId) { field.alert('ไม่พบ visit', 'warning'); return }
  const form = field.getFormRef()
  form.openForm('6a4689ef39179670f85ba2a2', dataId ? String(dataId) : null, String(visitId), null, {
    afterSaveCallback: () => { form.subFormClose(); s.loadBmi() }
  })
}

s.vsRec = null   // Vital Sign ล่าสุดของ visit นี้

// เกณฑ์ปกติ (ผู้ใหญ่) — นอกช่วง min-max = เตือนเหลือง (is-warning), แตะ dMin/dMax = แดง (is-danger)
// ปรับตัวเลขได้ที่นี่จุดเดียว
s.vsRules = {
  bp_h:  { min: 90, max: 140, dMin: 80, dMax: 180 },
  bp_l:  { min: 60, max: 90,  dMax: 110 },
  pulse: { min: 60, max: 100, dMin: 40, dMax: 130 },
  temp:  { min: 36, max: 37.4, dMin: 35, dMax: 38.5 },
  rr:    { min: 12, max: 20,  dMin: 8,  dMax: 30 }
}
s.vsClass = (name) => {
  const r = s.vsRules[name]
  const v = s.vsRec ? s.vsRec[name] : null
  if (!r || v == null || v === '') return ''
  if ((r.dMin != null && v <= r.dMin) || (r.dMax != null && v >= r.dMax)) return 'is-danger'
  if (v < r.min || v > r.max) return 'is-warning'
  return ''
}
// BP ใช้ระดับที่แย่กว่าระหว่างตัวบน/ตัวล่าง
s.bpClass = () => {
  const c = [s.vsClass('bp_h'), s.vsClass('bp_l')]
  return c.indexOf('is-danger') >= 0 ? 'is-danger' : (c.indexOf('is-warning') >= 0 ? 'is-warning' : '')
}

s.loadVs = () => {
  s.vsRec = null
  const visitId = s.tran && s.tran.vid && s.tran.vid.value
  if (!visitId) return
  field.getFormRef().userState.crudGetAll({
    sdProvider: {
      providerId: '6a470b4939179670f85ba2d8',   // ฟอร์ม Vital Sign
      providerType: 'FORM',
      params: { vid: String(visitId) },
      options: {
        where: "`vid.value` = CONVERT(:vid, 'objectId')",
        orderBy: [{ column: 'created_at', sort: 'DESC' }],
        limit: 1,
        page: 1
      }
    },
    totalEnable: false
  }, (res) => { s.vsRec = (res.data && res.data[0]) || null })
}

// เปิดฟอร์ม Vital Sign — dataId null = เพิ่มใหม่ (parent = visit), มีค่า = แก้ตัวล่าสุด
s.openVs = (dataId) => {
  const visitId = s.tran && s.tran.vid && s.tran.vid.value
  if (!visitId) { field.alert('ไม่พบ visit', 'warning'); return }
  const form = field.getFormRef()
  form.openForm('6a470b4939179670f85ba2d8', dataId ? String(dataId) : null, String(visitId), null, {
    afterSaveCallback: () => { form.subFormClose(); s.loadVs() }
  })
}

// ---- timer เวลาตรวจ — นับจาก start_at (stamp ตอนกดเริ่มตรวจ) เท่านั้น ----
// ยังไม่เริ่มตรวจ = '--:--' (ไม่ fallback checkin_at — นั่นคือเวลารอ ไม่ใช่เวลาตรวจ)
s.examClock = '--:--'
s.tickExam = () => {
  const t = s.tran && s.tran.start_at
  if (!t) { s.examClock = '--:--'; return }
  const sec = Math.max(0, Math.floor((new Date() - new Date(String(t).replace(' ', 'T'))) / 1000))
  const h = Math.floor(sec / 3600)
  const mm = String(Math.floor((sec % 3600) / 60)).padStart(2, '0')
  const ss = String(sec % 60).padStart(2, '0')
  s.examClock = h > 0 ? h + ':' + mm + ':' + ss : mm + ':' + ss
}

