if (s.examTimerId) clearInterval(s.examTimerId)
s.tickExam()
s.examTimerId = setInterval(s.tickExam, 1000)

options.onCreated:
const s = this.vueState
const field = this
const CONSULT_FORM = '6a482ea68ca8083d715e3498'
const TRAN_FORM = '6a461235e521219e514d1c4b'   // visit_tran — re-fetch หลังตอบ consult

s.tran = null
// ฝั่งรับ (clinic===unit_to) — คืน consult ทุก status ที่ recompute เก็บ (accept / complete+reply)
s.ci = () => {
  const t = s.tran
  if (!t || !t.consult_info) return null
  const c = t.consult_info
  const dest = c.clinic && t.unit_to && String(c.clinic) === String(t.unit_to.value)
  return dest ? c : null
}
s.fromLabel = () => (s.tran && s.tran.unit_from && s.tran.unit_from.label) || '-'
s.priorityText = () => { const c = s.ci(); return c ? ({ '20': 'เร่งด่วน', '30': 'STAT' })[String(c.priority)] || '' : '' }
s.priorityType = () => { const c = s.ci(); return c ? ({ '20': 'warning', '30': 'danger' })[String(c.priority)] || 'info' : 'info' }
s.load = (tran) => { s.tran = tran || null }

// เปิดฟอร์ม Consult (ตอบ/แก้คำตอบ) — send-back ทำที่ My Room ไม่ใช่ตรงนี้
s.answer = () => {
  const c = s.ci(); if (!c) return
  const form = field.getFormRef()
  const tranId = (s.tran && s.tran._id) ? String(s.tran._id) : ''
  const visitId = (s.tran && s.tran.vid && s.tran.vid.value) ? String(s.tran.vid.value) : ''
  form.openForm(CONSULT_FORM, String(c.consult_id), visitId, null, {
    afterSaveCallback: () => {
      form.subFormClose()
      // consult-sync-tran (api_onevent, ถูก await ตอน save) เพิ่งอัปเดต tran.consult_info ใน DB แล้ว
      // banner ผูกกับ snapshot tran เดิม → re-fetch tran ตัวเดิม แล้ว re-feed ผ่าน opd_card.setTran
      // (setTran กระจายให้ banner + consult_box + registry สดพร้อมกัน — จุดเดียวจบ)
      if (!tranId) return
      form.userState.crudGetAll({
        sdProvider: {
          providerId: TRAN_FORM,
          providerType: 'FORM',
          params: { tid: tranId },
          options: { where: "`_id` = CONVERT(:tid, 'objectId')", limit: 1, page: 1 }
        },
        totalEnable: false
      }, (res) => {
        const fresh = (res.data && res.data[0]) || null
        const opd = field.getFieldRef('opd_card')
        if (fresh && opd && opd.vueState && opd.vueState.setTran) opd.vueState.setTran(fresh)
      })
    }
  })
}

const s = this.vueState
const field = this
const CONSULT_FORM = '6a482ea68ca8083d715e3498'

s.items = null
s.visitId = null
s.showAll = false
s.toggleAll = () => { s.showAll = !s.showAll }

s.stLabel = (c) => c.consult_status === 'complete' ? 'ตอบแล้ว'
  : c.consult_status === 'accept' ? 'กำลังตรวจ'
  : ((c.consult_priority === '30' || c.consult_priority === '20') ? 'ด่วน · รอรับเรื่อง' : 'รอรับเรื่อง')
s.stClass = (c) => c.consult_status === 'complete' ? 'is-success'
  : c.consult_status === 'accept' ? 'is-warning'
  : ((c.consult_priority === '30' || c.consult_priority === '20') ? 'is-danger' : 'is-info')
s.toLabel = (c) => { const t = c.consult_to || {}; return t.value ? (t.value + ' — ' + (t.label || '')) : (t.label || '-') }
s.timeLabel = (c) => { if (!c || !c.created_at) return ''; const m = String(c.created_at).match(/\b(\d{2}:\d{2})\b/); return m ? m[1] : '' }

// localStorage ถูก sandbox shadow ใน vue-ui code (compileFn restricted) → undefined → เลิกใช้
// unread ต่อเครื่องทำไม่ได้ที่นี่ (อยากได้ข้ามเครื่องต้องเพิ่ม field read_at ในฟอร์ม Consult)
s.isUnread = () => false
s.unreadCount = () => 0
s.waitCount = () => (s.items || []).filter((c) => c.consult_status === 'send').length

s.rows = () => {
  const st = { send: 0, accept: 1, complete: 2 }
  const pr = { '30': 0, '20': 1, '10': 2 }
  const sorted = [...(s.items || [])].sort((a, b) =>
    ((st[a.consult_status] ?? 9) - (st[b.consult_status] ?? 9)) ||
    ((pr[a.consult_priority] ?? 9) - (pr[b.consult_priority] ?? 9)) ||
    String(b.created_at || '').localeCompare(String(a.created_at || '')))
  return s.showAll ? sorted : sorted.slice(0, 3)
}

s.load = (visitId) => {
  s.visitId = visitId ? String(visitId) : null
  s.items = null
  if (!s.visitId) { s.items = []; return }
  field.getFormRef().userState.crudGetAll({
    sdProvider: {
      providerId: CONSULT_FORM,
      providerType: 'FORM',
      params: { vid: s.visitId },
      options: {
        where: "`vid.value` = CONVERT(:vid, 'objectId')",
        orderBy: [{ column: 'created_at', sort: 'DESC' }],
        limit: 100,
        page: 1
      }
    },
    totalEnable: false
  }, (res) => { s.items = (res.data) || [] })
}

s.openRow = (c) => {
  const form = field.getFormRef()
  form.openForm(CONSULT_FORM, String(c._id), s.visitId, null, {
    readonly: c.consult_status !== 'send',   // send → แก้ได้ · accept/complete → readonly (ดูอย่างเดียว)
    afterSaveCallback: () => { form.subFormClose(); s.load(s.visitId) }
  })
}


s.addNew = () => {
  if (!s.visitId) { field.alert('ยังไม่ได้เลือกคนไข้', 'warning'); return }
  const form = field.getFormRef()
  form.openForm(CONSULT_FORM, null, s.visitId, null, {
    afterSaveCallback: () => { form.subFormClose(); s.load(s.visitId) }
  })
}

